"""Three fresh full processes after freeze; compare every generated byte and SHA256."""
import json,shutil,subprocess,sys
from pathlib import Path
from support import HERE,WORK
from io_utils import digest,write_json

def inventory(folder):return {str(p.relative_to(folder)):digest(p) for p in sorted(folder.rglob('*')) if p.is_file()}

def main():
 freeze=json.loads((HERE/'CODE_FREEZE.json').read_text())
 for name,expected in freeze['files'].items():assert digest(HERE/name)==expected,('CODE_CHANGED',name)
 folders=[WORK/('final'+str(i)) for i in (1,2,3)]
 for i,folder in enumerate(folders,1):
  assert not folder.exists(),('FRESH_RUN_REQUIRED',str(folder))
  with (WORK/f'final{i}.log').open('w') as log:subprocess.run([sys.executable,str(HERE/'run.py'),'--output',str(folder)],stdout=log,stderr=subprocess.STDOUT,check=True)
  print('FRESH_FULL_PROCESS_COMPLETED',i,flush=True)
 baseline=inventory(folders[0]);comparisons=[]
 for folder in folders[1:]:
  current=inventory(folder);assert baseline==current,('SHA_MISMATCH',str(folder))
  assert all((folders[0]/rel).read_bytes()==(folder/rel).read_bytes() for rel in baseline),'BYTE_MISMATCH'
  comparisons.append(dict(run=folder.name,direct_bytes_equal=True,sha256_equal=True,files=len(baseline)))
 for rel in baseline:
  target=HERE/rel;target.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(folders[0]/rel,target)
 write_json(HERE/'REPEATABILITY.json',dict(status='PASS',code_freeze_sha256=digest(HERE/'CODE_FREEZE.json'),first_full_process='final1',fresh_repeats=2,compared_generated_files=len(baseline),files_sha256=baseline,comparisons=comparisons,scope='Every artifact emitted by run.py including full CONTROL receipts, both development replays, scalar/Decimal checks, tests, Russian report, audit; source documentation/code and this receipt are outside generated set'))
 print('REPEATABILITY PASS',len(baseline),flush=True)
if __name__=='__main__':main()
